//! Acceptance coverage for 別紙C §18.3.13 テスト仕様書の出力 (DS-S164:
//! DS-1780〜DS-1811).
//!
//! The clauses that name the shipped `vtest` run the binary; the clauses
//! that name the acceptance-only registry call the export operation
//! in-process with `rust-cargo` and `synthetic` registered, because
//! `synthetic` is not in the shipped registry. The Markdown document of an
//! in-process result is generated by the part the CLI uses
//! (`test_spec_markdown::render_test_specification`).

mod support;

use std::{fs, path::Path};

use serde_json::{json, Value};
use support::spec_acceptance::{
    acceptance_registry, codes, commit, exit, json_of, keys, mcp_call, mcp_input_schema,
    mixed_project, run_test, rust_project, rust_project_with, stderr, stdout, submit_judgment,
    test_ids, tree, vtest, Project, GONE_RS, LIB_RS, TESTS_RS,
};
use vtest_cli::test_spec_markdown::{markdown_encoding, render_test_specification};
use vtest_scan::TestSpecification;

/// The export operation in-process: its data, which the scan must have
/// produced.
fn exported(project: &Project, reversed: bool) -> TestSpecification {
    vtest_ops::export::execute(&project.root, &acceptance_registry(reversed))
        .data
        .expect("the scan completes, so the operation returns data")
}

fn to_json(data: &TestSpecification) -> Value {
    serde_json::to_value(data).expect("serialize data")
}

/// The lines of one `## ` section of the document, without its heading.
fn section<'a>(document: &'a str, heading: &str) -> Vec<&'a str> {
    document
        .lines()
        .skip_while(|line| *line != heading)
        .skip(1)
        .take_while(|line| !line.starts_with("## "))
        .collect()
}

fn items(lines: &[&str]) -> Vec<String> {
    lines
        .iter()
        .filter(|line| line.starts_with("- "))
        .map(|line| (*line).to_owned())
        .collect()
}

/// `vtest export --format json`: exit code and envelope.
fn export_json(root: &Path) -> (i32, Value) {
    json_of(root, &["export"])
}

/// `vtest export --format md`: exit code and stdout.
fn export_md(root: &Path) -> (i32, String) {
    let output = vtest(root, &["export", "--format", "md"]);
    (exit(&output), stdout(&output))
}

const TEST_ITEM_LINES: [&str; 11] = [
    "- intent:",
    "- covers:",
    "- targets:",
    "- input:",
    "- expect:",
    "- kind:",
    "- cases:",
    "- related:",
    "- adapter:",
    "- path:",
    "- locator:",
];

/// @vtest.id TEST-ACCEPTANCE-EXPORT-MIXED-ADAPTERS-SAME-FORM
/// @vtest.covers VO-ACCEPTANCE-EXPORT-MIXED-TESTS-ELEVEN-KEYS, VO-ACCEPTANCE-EXPORT-MIXED-MARKDOWN-ITEM-LINES
/// @vtest.target crates/vtest-ops/src/export.rs::execute
/// @vtest.target crates/vtest-cli/src/test_spec_markdown.rs::render_test_specification
/// @vtest.intent the export operation given the acceptance-only registry of `rust-cargo` and `synthetic` returns the managed Tests of both adapters in `data.tests`, every element with the same eleven keys only, and the `## Tests` section of the Markdown document generated from that data has, for every Test of either adapter, the eleven line starts from `- intent:` to `- locator:` in the same order
#[test]
fn a_mixed_project_exports_the_tests_of_both_adapters_in_one_form() {
    let project = mixed_project("export-mixed");
    let data = exported(&project, false);
    let json = to_json(&data);
    let tests = json["tests"].as_array().unwrap();
    for adapter in ["rust-cargo", "synthetic"] {
        assert!(
            tests
                .iter()
                .any(|test| test["location"]["adapter"] == adapter),
            "no {adapter} Test in {json}"
        );
    }
    let mut expected = vec![
        "key", "id", "intent", "covers", "targets", "input", "expect", "kind", "cases", "related",
        "location",
    ];
    expected.sort_unstable();
    for test in tests {
        assert_eq!(keys(test), expected, "{test}");
    }

    let document = render_test_specification(&data);
    let lines = section(&document, "## Tests");
    let headings: Vec<usize> = lines
        .iter()
        .enumerate()
        .filter(|(_, line)| line.starts_with("### "))
        .map(|(index, _)| index)
        .collect();
    assert_eq!(headings.len(), tests.len(), "{document}");
    for (position, start) in headings.iter().enumerate() {
        let end = headings.get(position + 1).copied().unwrap_or(lines.len());
        let starts: Vec<&str> = lines[*start..end]
            .iter()
            .filter(|line| line.starts_with("- "))
            .map(|line| &line[..line.find(':').map_or(line.len(), |colon| colon + 1)])
            .collect();
        assert_eq!(starts, TEST_ITEM_LINES, "item {position} of:\n{document}");
    }
    let adapters = items(&lines)
        .into_iter()
        .filter(|line| line.starts_with("- adapter:"))
        .collect::<Vec<_>>();
    assert!(adapters.iter().any(|line| line.contains("synthetic")));
    assert!(adapters.iter().any(|line| line.contains("rust\\-cargo")));
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-UNMANAGED-CONSTRUCT
/// @vtest.covers VO-ACCEPTANCE-EXPORT-UNMANAGED-W-SCAN-101, VO-ACCEPTANCE-EXPORT-WARNING-ONLY-EXIT-0, VO-ACCEPTANCE-EXPORT-INCOMPLETE-DECLARATION-UNMANAGED
/// @vtest.target crates/vtest-ops/src/export.rs::execute
/// @vtest.intent a test function without a declaration is not in `data.tests` and is in `data.unmanaged` with W-SCAN-101 in `codes` and one line under `## Unmanaged tests`, and with W-SCAN-101 as the only scan diagnostic `vtest export` exits 0 with `ok: true`; a construct with an incomplete declaration is not in `data.tests` either and is in `data.unmanaged` with the E-SCAN code the scan attached to it
/// @vtest.case no declaration
/// @vtest.case incomplete declaration
#[test]
fn constructs_without_a_complete_declaration_are_exported_as_unmanaged() {
    let project = rust_project("export-unmanaged");
    let (code, exported) = export_json(&project.root);
    assert_eq!(code, 0, "{exported}");
    assert_eq!(exported["ok"], true);
    assert_eq!(codes(&exported), ["W-SCAN-101"]);
    let data = &exported["data"];
    assert_eq!(test_ids(data).len(), 3);
    let unmanaged = data["unmanaged"].as_array().unwrap();
    assert_eq!(unmanaged.len(), 1, "{data}");
    assert_eq!(unmanaged[0]["location"]["locator"], "bare");
    assert_eq!(unmanaged[0]["codes"], json!(["W-SCAN-101"]));
    assert!(data["tests"]
        .as_array()
        .unwrap()
        .iter()
        .all(|test| test["location"]["locator"] != "bare"));
    let (code, document) = export_md(&project.root);
    assert_eq!(code, 0);
    let lines = items(&section(&document, "## Unmanaged tests"));
    assert_eq!(lines.len(), 1, "{document}");
    assert!(lines[0].contains("bare") && lines[0].contains("W\\-SCAN\\-101"));

    project.write(
        "tests/incomplete.rs",
        "/// @vtest.id TEST-INCOMPLETE\n/// @vtest.intent has no covers\n\
         #[test]\nfn incomplete() {}\n",
    );
    let (code, exported) = export_json(&project.root);
    assert_eq!(code, 1, "{exported}");
    let data = &exported["data"];
    assert!(!test_ids(data).contains(&"TEST-INCOMPLETE".to_owned()));
    let incomplete = data["unmanaged"]
        .as_array()
        .unwrap()
        .iter()
        .find(|entry| entry["location"]["locator"] == "incomplete")
        .unwrap_or_else(|| panic!("incomplete is not unmanaged: {data}"));
    let attached: Vec<&str> = incomplete["codes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|code| code.as_str().unwrap())
        .collect();
    assert!(!attached.is_empty(), "{incomplete}");
    assert!(
        attached.iter().all(|code| code.starts_with("E-SCAN-")),
        "{incomplete}"
    );
    for code in attached {
        assert!(codes(&exported).contains(&code.to_owned()), "{exported}");
    }
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-UNRESOLVED-REFERENCES
/// @vtest.covers VO-ACCEPTANCE-EXPORT-UNRESOLVED-COVERS-KEPT, VO-ACCEPTANCE-EXPORT-UNRESOLVED-COVERS-EXIT-1, VO-ACCEPTANCE-EXPORT-UNRESOLVED-TARGET-KEPT, VO-ACCEPTANCE-EXPORT-UNRESOLVED-RELATED-NO-CODE
/// @vtest.target crates/vtest-ops/src/export.rs::execute
/// @vtest.intent a Test with an unresolved `covers` stays in `data.tests` with `claim: null`, is in `data.unresolved` with field `covers` and E-SCAN-003 and on one line under `## Unresolved references`, and `vtest export` exits 1 with `ok: false`, non-null `data` and the Markdown document on stdout; a Test with an unresolved target stays with `resolved: false` and an `unresolved` element of field `target`; a `related` reference to no Test is in `data.unresolved` with field `related` and `code: null` and leaves the exit code 0
/// @vtest.case unresolved covers
/// @vtest.case unresolved target
/// @vtest.case related to no Test
#[test]
fn unresolved_references_are_exported_and_not_dropped() {
    let project = rust_project("export-unresolved-covers");
    project.write("tests/gone.rs", GONE_RS);
    let (code, exported) = export_json(&project.root);
    assert_eq!(code, 1, "{exported}");
    assert_eq!(exported["ok"], false);
    let data = &exported["data"];
    assert!(!data.is_null());
    let gone = data["tests"]
        .as_array()
        .unwrap()
        .iter()
        .find(|test| test["id"] == "TEST-GONE")
        .unwrap_or_else(|| panic!("TEST-GONE dropped: {data}"));
    assert_eq!(gone["covers"], json!([{"vo": "VO-GONE", "claim": null}]));
    let unresolved = data["unresolved"].as_array().unwrap();
    assert_eq!(unresolved.len(), 1, "{data}");
    assert_eq!(unresolved[0]["field"], "covers");
    assert_eq!(unresolved[0]["code"], "E-SCAN-003");
    let (code, document) = export_md(&project.root);
    assert_eq!(code, 1);
    assert!(document.starts_with("# Test Specification"), "{document}");
    let lines = items(&section(&document, "## Unresolved references"));
    assert_eq!(lines.len(), 1, "{document}");
    assert!(lines[0].contains("covers") && lines[0].contains("VO\\-GONE"));

    let project = rust_project_with(
        "export-unresolved-target",
        LIB_RS,
        &TESTS_RS.replace("src/lib.rs::sub", "src/lib.rs::missing"),
    );
    let (code, exported) = export_json(&project.root);
    assert_eq!(code, 1, "{exported}");
    let data = &exported["data"];
    let sub = data["tests"]
        .as_array()
        .unwrap()
        .iter()
        .find(|test| test["id"] == "TEST-SUB")
        .unwrap_or_else(|| panic!("TEST-SUB dropped: {data}"));
    assert_eq!(sub["targets"].as_array().map(Vec::len), Some(1));
    assert_eq!(sub["targets"][0]["resolved"], false);
    let unresolved = data["unresolved"].as_array().unwrap();
    assert_eq!(unresolved.len(), 1, "{data}");
    assert_eq!(unresolved[0]["field"], "target");

    let project = rust_project_with(
        "export-unresolved-related",
        LIB_RS,
        &TESTS_RS.replace(
            "/// @vtest.intent adds two numbers\n",
            "/// @vtest.intent adds two numbers\n/// @vtest.related TEST-NOWHERE\n",
        ),
    );
    let (code, exported) = export_json(&project.root);
    assert_eq!(code, 0, "{exported}");
    assert_eq!(exported["ok"], true);
    let unresolved = exported["data"]["unresolved"].as_array().unwrap();
    assert_eq!(unresolved.len(), 1, "{exported}");
    assert_eq!(unresolved[0]["field"], "related");
    assert_eq!(unresolved[0]["code"], Value::Null);
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-DUPLICATED-TEST-ID-KEYS
/// @vtest.covers VO-ACCEPTANCE-EXPORT-DUPLICATED-ID-KEYS
/// @vtest.target crates/vtest-ops/src/export.rs::execute
/// @vtest.intent two managed Tests with the same Test ID are both in `data.tests`, with the keys of the Test ID followed by `~1` and `~2`
#[test]
fn two_tests_with_one_id_are_both_exported_with_numbered_keys() {
    let project = rust_project("export-duplicate");
    project.write(
        "tests/again.rs",
        "/// @vtest.id TEST-ADD\n/// @vtest.covers VO-X\n\
         /// @vtest.target src/lib.rs::add\n/// @vtest.intent adds again\n\
         #[test]\nfn adds_twice() {}\n",
    );
    let (_, exported) = export_json(&project.root);
    let keys: Vec<&str> = exported["data"]["tests"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|test| test["id"] == "TEST-ADD")
        .map(|test| test["key"].as_str().unwrap())
        .collect();
    assert_eq!(keys, ["TEST-ADD~1", "TEST-ADD~2"], "{exported}");
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-DETERMINISTIC
/// @vtest.covers VO-ACCEPTANCE-EXPORT-REPEATED-RUNS-IDENTICAL, VO-ACCEPTANCE-EXPORT-REVERSED-ENUMERATION-IDENTICAL
/// @vtest.target crates/vtest-ops/src/export.rs::execute
/// @vtest.target crates/vtest-cli/src/test_spec_markdown.rs::render_test_specification
/// @vtest.intent two runs of `vtest export` on the same repository content give byte-identical JSON `data` and byte-identical Markdown; and with the acceptance-only registry, registering the adapters in the opposite order and reversing every enumeration the `synthetic` adapter returns gives byte-identical serialized `data` and a byte-identical Markdown document
/// @vtest.case repeated runs of the shipped binary
/// @vtest.case reversed registration and enumeration
#[test]
fn the_export_does_not_depend_on_the_run_or_on_enumeration_order() {
    let project = rust_project("export-repeat");
    project.write("tests/gone.rs", GONE_RS);
    let first = vtest(&project.root, &["export", "--format", "json"]);
    let second = vtest(&project.root, &["export", "--format", "json"]);
    let data = |output: &std::process::Output| {
        let envelope: Value = serde_json::from_slice(&output.stdout).unwrap();
        serde_json::to_string(&envelope["data"]).unwrap()
    };
    assert_eq!(data(&first), data(&second));
    assert_eq!(first.stdout, second.stdout);
    let first = vtest(&project.root, &["export", "--format", "md"]);
    let second = vtest(&project.root, &["export", "--format", "md"]);
    assert!(!first.stdout.is_empty());
    assert_eq!(first.stdout, second.stdout);

    let mixed = mixed_project("export-reversed");
    let forward = exported(&mixed, false);
    let reversed = exported(&mixed, true);
    assert_eq!(forward.tests.len(), 5);
    assert_eq!(
        serde_json::to_string(&forward).unwrap(),
        serde_json::to_string(&reversed).unwrap()
    );
    assert_eq!(
        render_test_specification(&forward),
        render_test_specification(&reversed)
    );
}

fn heading_and_line_counts(document: &str) -> (usize, usize) {
    (
        document
            .lines()
            .filter(|line| line.starts_with('#'))
            .count(),
        document.lines().count(),
    )
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-MARKDOWN-STRUCTURE-KEPT
/// @vtest.covers VO-ACCEPTANCE-EXPORT-HOSTILE-VALUES-KEEP-LINE-COUNTS
/// @vtest.target crates/vtest-cli/src/test_spec_markdown.rs::render_test_specification
/// @vtest.intent a Test whose declared values contain the characters Markdown may read as notation (`#`, `|`, a backtick, `<`, `*`, `[`) gives a document with the same number of lines and of heading lines as the same declaration with alphanumeric values, through the shipped `vtest export`; and with a line feed added to the values of the exported data, the document generated from it keeps both counts as well
/// @vtest.case declared symbols through the shipped binary
/// @vtest.case line feed in the data
#[test]
fn values_that_look_like_markdown_do_not_change_the_document_structure() {
    let hostile = "# a | b ` c < d * e [f](g)";
    let declare = |value: &str| {
        TESTS_RS.replace(
            "/// @vtest.intent adds two numbers\n",
            &format!(
                "/// @vtest.intent {value}\n/// @vtest.input {value}\n\
                 /// @vtest.expect {value}\n/// @vtest.case {value}\n"
            ),
        )
    };
    let plain = rust_project_with("export-plain", LIB_RS, &declare("abc123"));
    let symbols = rust_project_with("export-symbols", LIB_RS, &declare(hostile));
    let (plain_code, plain_document) = export_md(&plain.root);
    let (symbols_code, symbols_document) = export_md(&symbols.root);
    assert_eq!((plain_code, symbols_code), (0, 0));
    let (_, exported) = export_json(&symbols.root);
    assert!(
        exported["data"]["tests"]
            .as_array()
            .unwrap()
            .iter()
            .any(|test| test["intent"] == hostile && test["cases"] == json!([hostile])),
        "the declared value did not reach the data: {exported}"
    );
    assert_eq!(
        heading_and_line_counts(&symbols_document),
        heading_and_line_counts(&plain_document)
    );

    let mut data = vtest_ops::export::execute(&plain.root, &acceptance_registry(false))
        .data
        .unwrap();
    let before = heading_and_line_counts(&render_test_specification(&data));
    let with_line_feed = format!("{hostile}\n# heading\n- item\n\n| a |");
    for test in &mut data.tests {
        test.intent.clone_from(&with_line_feed);
        test.input = Some(with_line_feed.clone());
        test.expect = Some(with_line_feed.clone());
        test.kind = Some(with_line_feed.clone());
        // An empty list is one `(none)` line, so only existing cases change.
        for case in &mut test.cases {
            case.clone_from(&with_line_feed);
        }
    }
    assert!(data.tests.iter().any(|test| !test.cases.is_empty()));
    assert_eq!(
        heading_and_line_counts(&render_test_specification(&data)),
        before
    );
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-MCP-MATCHES-CLI
/// @vtest.covers VO-ACCEPTANCE-EXPORT-MCP-EQUALS-CLI-JSON, VO-ACCEPTANCE-EXPORT-MCP-IS-ERROR-FROM-OK, VO-ACCEPTANCE-EXPORT-MCP-ARGUMENT-REJECTED, VO-ACCEPTANCE-EXPORT-MCP-LISTED-WITHOUT-PROPERTIES
/// @vtest.target crates/vtest-mcp/src/lib.rs::tools_call_result
/// @vtest.intent over the real `vtest mcp` stdio transport, `tools/list` names `export` with an input schema without properties; the result of `export` equals the JSON of `vtest export --format json` in `ok`, `data` and `diagnostics` without and with an error diagnostic; `isError` is false for `ok: true` and true for `ok: false` with non-null and with null `data`; a call with an argument is an E-OP-001 tool error
/// @vtest.case no error diagnostic
/// @vtest.case error diagnostic, data present
/// @vtest.case rejected config, data null
/// @vtest.case argument given
#[test]
fn the_mcp_export_tool_returns_what_the_cli_prints() {
    let project = rust_project("export-mcp");
    let schema = mcp_input_schema(&project.root, "export").expect("export is listed");
    assert_eq!(schema["properties"], json!({}));

    let compare = |expected_ok: bool, data_is_null: bool| {
        let (_, via_cli) = export_json(&project.root);
        let via_mcp = mcp_call(&project.root, "export", json!({}));
        let envelope = &via_mcp["structuredContent"];
        for key in ["ok", "data", "diagnostics"] {
            assert_eq!(envelope[key], via_cli[key], "{key}");
        }
        assert_eq!(via_cli["ok"], expected_ok, "{via_cli}");
        assert_eq!(via_cli["data"].is_null(), data_is_null, "{via_cli}");
        assert_eq!(via_mcp["isError"], !expected_ok, "{via_mcp}");
    };
    compare(true, false);

    let rejected = mcp_call(&project.root, "export", json!({"format": "md"}));
    assert_eq!(rejected["isError"], true, "{rejected}");
    assert_eq!(
        rejected["structuredContent"]["diagnostics"][0]["code"],
        "E-OP-001"
    );

    project.write("tests/gone.rs", GONE_RS);
    compare(false, false);
    project.write(".verify/config.yaml", "version: 2\nproject: [\n");
    compare(false, true);
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-IGNORES-EVIDENCE-APPROVALS-JUDGMENTS
/// @vtest.covers VO-ACCEPTANCE-EXPORT-UNCHANGED-BY-RECORDS, VO-ACCEPTANCE-EXPORT-EXIT-0-WHEN-VERIFY-NG
/// @vtest.target crates/vtest-ops/src/export.rs::execute
/// @vtest.intent `vtest verify` is NG for a project whose only scan diagnostic is a warning while `vtest export` exits 0 with `ok: true`; and adding a valid Evidence record, an approval record and a judgment record, and deleting them again, leaves the JSON `data` and the Markdown stdout byte-identical
/// @vtest.case records added
/// @vtest.case records deleted
#[test]
fn evidence_approvals_and_judgments_do_not_change_the_export() {
    let project = rust_project("export-records");
    commit(&project.root);
    let root = &project.root;

    let (verify_code, verified) = json_of(root, &["verify"]);
    assert_eq!(verify_code, 1, "{verified}");
    assert_eq!(verified["ok"], false);
    let (code, exported) = export_json(root);
    assert_eq!(code, 0, "{exported}");
    assert_eq!(exported["ok"], true);

    let snapshot = |root: &Path| {
        let (_, exported) = export_json(root);
        (
            serde_json::to_string(&exported["data"]).unwrap(),
            vtest(root, &["export", "--format", "md"]).stdout,
        )
    };
    let records = |root: &Path| -> Vec<String> {
        tree(&root.join(".verify"))
            .into_iter()
            .filter(|(path, bytes)| bytes.is_some() && !path.starts_with("cache"))
            .map(|(path, _)| path)
            .collect()
    };
    let before = snapshot(root);
    let records_before = records(root);

    run_test(root, "TEST-ADD");
    submit_judgment(root, "TEST-ADD", "case-coverage", "accepted", &[]);
    let (code, approved) = json_of(
        root,
        &[
            "approval",
            "create",
            "--subject-type",
            "vo",
            "--subject-id",
            "VO-X",
            "--state",
            "approved",
            "--approver-kind",
            "agent",
            "--approver-id",
            "bot",
            "--model",
            "m",
        ],
    );
    assert_eq!(code, 0, "{approved}");
    let added: Vec<String> = records(root)
        .into_iter()
        .filter(|path| !records_before.contains(path))
        .collect();
    for directory in ["evidence", "decisions", "approvals"] {
        assert!(
            added.iter().any(|path| path.starts_with(directory)),
            "no new record under .verify/{directory}: {added:?}"
        );
    }
    assert!(snapshot(root) == before, "records added");

    for path in &added {
        fs::remove_file(root.join(".verify").join(path)).unwrap();
    }
    assert_eq!(records(root), records_before);
    assert!(snapshot(root) == before, "records deleted");
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-WRITES-NOTHING
/// @vtest.covers VO-ACCEPTANCE-EXPORT-PROJECT-FILES-UNCHANGED
/// @vtest.target crates/vtest-ops/src/export.rs::execute
/// @vtest.intent the set of files and directories below the project root and the content of every file are the same before and after `vtest export` in Markdown and JSON and after a call of the MCP tool `export`
#[test]
fn export_leaves_the_project_files_as_they_were() {
    let project = rust_project("export-no-writes");
    project.write("tests/gone.rs", GONE_RS);
    let before = tree(&project.root);
    vtest(&project.root, &["export"]);
    assert!(tree(&project.root) == before, "export --format md");
    vtest(&project.root, &["export", "--format", "json"]);
    assert!(tree(&project.root) == before, "export --format json");
    let called = mcp_call(&project.root, "export", json!({}));
    assert!(!called["structuredContent"]["data"].is_null(), "{called}");
    assert!(tree(&project.root) == before, "MCP export");
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-WITHOUT-DOCUMENT-RECORDS
/// @vtest.covers VO-ACCEPTANCE-EXPORT-NO-DOCUMENT-RECORDS
/// @vtest.target crates/vtest-ops/src/export.rs::execute
/// @vtest.intent in a project without any document record, `vtest export` prints the test specification with the project's Tests
#[test]
fn a_project_without_document_records_is_exported() {
    let project = rust_project("export-no-documents");
    let documents = project.root.join(".verify/doc");
    assert!(documents.is_dir());
    fs::remove_dir_all(&documents).unwrap();
    fs::create_dir(&documents).unwrap();
    let (_, exported) = export_json(&project.root);
    assert_eq!(test_ids(&exported["data"]).len(), 3, "{exported}");
    let (_, document) = export_md(&project.root);
    assert!(document.starts_with("# Test Specification"), "{document}");
    assert!(document.contains("TEST\\-ADD"), "{document}");
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-REJECTED-CONFIG-AND-QUIET
/// @vtest.covers VO-ACCEPTANCE-EXPORT-REJECTED-CONFIG-OUTPUT, VO-ACCEPTANCE-EXPORT-QUIET-EXIT-CODES
/// @vtest.target crates/vtest-cli/src/lib.rs::run_export
/// @vtest.intent with a config rejected by E-CONFIG-001, `vtest export --format json` exits 2 and prints an `ok: false`, `data: null` envelope on stdout, and `--format md` exits 2 with nothing on stdout and the diagnostic on stderr; and `vtest export --quiet` prints nothing on stdout and stderr and returns the same exit code as without `--quiet`, when that is 0, 1, 2 and 3
/// @vtest.case exit code 0
/// @vtest.case exit code 1
/// @vtest.case exit code 2
/// @vtest.case exit code 3
#[test]
fn a_rejected_config_and_quiet_keep_the_exit_code_of_export() {
    let ok = rust_project("export-quiet-ok");
    let failed = rust_project("export-quiet-failed");
    failed.write("tests/gone.rs", GONE_RS);
    let rejected = rust_project("export-quiet-rejected");
    rejected.write(".verify/config.yaml", "version: 2\nproject: [\n");
    let internal = rust_project("export-quiet-internal");
    let config = internal.root.join(".verify/config.yaml");
    fs::remove_file(&config).unwrap();
    fs::create_dir(&config).unwrap();

    let (code, envelope) = export_json(&rejected.root);
    assert_eq!(code, 2, "{envelope}");
    assert_eq!(envelope["ok"], false);
    assert_eq!(envelope["data"], Value::Null);
    assert_eq!(codes(&envelope), ["E-CONFIG-001"]);
    let markdown = vtest(&rejected.root, &["export", "--format", "md"]);
    assert_eq!(exit(&markdown), 2);
    assert_eq!(stdout(&markdown), "");
    assert!(stderr(&markdown).contains("E-CONFIG-001"), "{markdown:?}");

    for (project, expected) in [(&ok, 0), (&failed, 1), (&rejected, 2), (&internal, 3)] {
        for format in ["md", "json"] {
            let loud = vtest(&project.root, &["export", "--format", format]);
            assert_eq!(exit(&loud), expected, "{format}");
            let quiet = vtest(&project.root, &["export", "--format", format, "--quiet"]);
            assert_eq!(exit(&quiet), expected, "{format} --quiet");
            assert!(quiet.stdout.is_empty(), "{expected} {format}");
            assert!(quiet.stderr.is_empty(), "{expected} {format}");
        }
    }
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-REJECTED-ARGUMENTS
/// @vtest.covers VO-ACCEPTANCE-EXPORT-FORMAT-TEXT-AND-MD-ELSEWHERE-REJECTED, VO-ACCEPTANCE-EXPORT-JSON-EXTRA-POSITIONAL-REJECTED, VO-ACCEPTANCE-EXPORT-JSON-UNKNOWN-OPTION-REJECTED, VO-ACCEPTANCE-EXPORT-MD-EXTRA-ARGUMENTS-REJECTED, VO-ACCEPTANCE-EXPORT-QUIET-EXTRA-ARGUMENTS-SILENT
/// @vtest.target crates/vtest-cli/src/lib.rs::run
/// @vtest.intent `vtest export --format text` and `--format md` on a command other than `export` exit 2; an extra positional argument or an option other than `--project`, `--format` and `--quiet` given to `vtest export` in JSON and in Markdown exits 2 with nothing on stdout and the argument error on stderr, and with `--quiet` exits 2 with nothing on stdout and stderr
/// @vtest.case --format text on export, --format md on other commands
/// @vtest.case extra positional argument
/// @vtest.case unknown option
/// @vtest.case with --quiet
#[test]
fn export_rejects_formats_and_arguments_outside_its_contract() {
    let project = rust_project("export-arguments");
    let root = &project.root;
    assert_eq!(exit(&vtest(root, &["export", "--format", "text"])), 2);
    for command in [
        vec!["scan"],
        vec!["verify"],
        vec!["doctor"],
        vec!["test", "list"],
    ] {
        let mut args = vec!["--format", "md"];
        args.extend_from_slice(&command);
        assert_eq!(exit(&vtest(root, &args)), 2, "{command:?}");
    }

    for format in ["json", "md"] {
        for extra in [
            vec!["extra"],
            vec!["--output", "spec.md"],
            vec!["--vo", "VO-X"],
        ] {
            let mut args = vec!["export", "--format", format];
            args.extend_from_slice(&extra);
            let loud = vtest(root, &args);
            assert_eq!(exit(&loud), 2, "{args:?}");
            assert_eq!(stdout(&loud), "", "{args:?}");
            assert_ne!(stderr(&loud), "", "{args:?}");

            args.push("--quiet");
            let quiet = vtest(root, &args);
            assert_eq!(exit(&quiet), 2, "{args:?}");
            assert!(quiet.stdout.is_empty(), "{args:?}");
            assert!(quiet.stderr.is_empty(), "{args:?}");
        }
    }
    assert!(!root.join("spec.md").exists());
}

/// The inverse of the Markdown encoding of DS-1747.
fn decode(encoded: &str) -> String {
    let mut out = String::new();
    let mut rest = encoded;
    while let Some(first) = rest.chars().next() {
        if let Some(after) = rest.strip_prefix("<br>") {
            out.push('\n');
            rest = after;
        } else if let Some(after) = rest.strip_prefix("&#") {
            let end = after.find(';').expect("terminated reference");
            let code: u32 = after[..end].parse().expect("decimal code point");
            out.push(char::from_u32(code).expect("code point"));
            rest = &after[end + 1..];
        } else if first == '\\' {
            let escaped = rest[1..].chars().next().expect("escaped character");
            out.push(escaped);
            rest = &rest[1 + escaped.len_utf8()..];
        } else {
            out.push(first);
            rest = &rest[first.len_utf8()..];
        }
    }
    out
}

/// The `- intent: ` line of the first Test of the document generated from
/// `data` with that Test's intent set to `value`.
fn intent_in_document(data: &TestSpecification, value: &str) -> String {
    let mut data = data.clone();
    data.tests[0].intent = value.to_owned();
    let document = render_test_specification(&data);
    section(&document, "## Tests")
        .into_iter()
        .find_map(|line| line.strip_prefix("- intent: "))
        .expect("an intent line")
        .to_owned()
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-MARKDOWN-ENCODING
/// @vtest.covers VO-ACCEPTANCE-EXPORT-ASCII-SYMBOLS-ESCAPED, VO-ACCEPTANCE-EXPORT-CONTROLS-AND-EDGE-SPACES-REPLACED, VO-ACCEPTANCE-EXPORT-ENCODING-REVERSIBLE
/// @vtest.target crates/vtest-cli/src/test_spec_markdown.rs::markdown_encoding
/// @vtest.target crates/vtest-cli/src/test_spec_markdown.rs::render_test_specification
/// @vtest.intent in the document generated from exported data, a value with all 32 ASCII symbols has each of them, in order, behind a backslash; a value with LF, other C0 controls, U+007F and leading and trailing spaces has `<br>`, decimal character references and `&#32;` in their places and the other characters unchanged; and for a value mixing all of these with non-ASCII characters, undoing the replacements gives the original bytes
/// @vtest.case all 32 ASCII symbols
/// @vtest.case controls and edge spaces
/// @vtest.case mixed value round trip
#[test]
fn markdown_values_are_encoded_without_losing_a_character() {
    let project = rust_project("export-encoding");
    let data = vtest_ops::export::execute(&project.root, &acceptance_registry(false))
        .data
        .unwrap();

    let symbols: String = ('\u{21}'..='\u{2f}')
        .chain('\u{3a}'..='\u{40}')
        .chain('\u{5b}'..='\u{60}')
        .chain('\u{7b}'..='\u{7e}')
        .collect();
    assert_eq!(symbols.chars().count(), 32);
    let value = format!("a{symbols}z");
    let expected: String = symbols.chars().flat_map(|symbol| ['\\', symbol]).collect();
    assert_eq!(intent_in_document(&data, &value), format!("a{expected}z"));

    let controls = "  two\nlines\ttab\u{0}nul\u{1f}unit\u{7f}del inner  space ";
    assert_eq!(
        intent_in_document(&data, controls),
        "&#32;&#32;two<br>lines&#9;tab&#0;nul&#31;unit&#127;del inner  space&#32;"
    );

    let mixed = format!(" {symbols}\n日本語\u{1}\u{7f}é\r\n*終わり*  ");
    let encoded = intent_in_document(&data, &mixed);
    assert_eq!(encoded, markdown_encoding(&mixed));
    assert!(!encoded.contains('\n'));
    assert_eq!(decode(&encoded).as_bytes(), mixed.as_bytes());
}

/// @vtest.id TEST-ACCEPTANCE-EXPORT-SHIPPED-BINARY-EQUALS-OPERATION
/// @vtest.covers VO-ACCEPTANCE-EXPORT-SHIPPED-EQUALS-IN-PROCESS
/// @vtest.target crates/vtest-cli/src/lib.rs::run_export
/// @vtest.target crates/vtest-ops/src/export.rs::execute
/// @vtest.intent for a `rust-cargo` project with managed Tests, a test function without a declaration and an unresolved reference, the `data` of the shipped `vtest export --format json` equals the `data` the export operation returns in-process with the shipped registry, and the stdout of `vtest export --format md` is byte-identical to the document the CLI's Markdown part generates from that data
#[test]
fn the_shipped_export_prints_the_data_and_document_of_the_operation() {
    let project = rust_project("export-shipped");
    project.write("tests/gone.rs", GONE_RS);
    let registry = vtest_ops::registry::builtin_registry().expect("builtin registry");
    let data = vtest_ops::export::execute(&project.root, &registry)
        .data
        .expect("data");
    assert!(!data.tests.is_empty() && !data.unmanaged.is_empty() && !data.unresolved.is_empty());

    let (code, exported) = export_json(&project.root);
    assert_eq!(code, 1);
    assert_eq!(exported["data"], to_json(&data));
    let (code, document) = export_md(&project.root);
    assert_eq!(code, 1);
    assert_eq!(document, render_test_specification(&data));
}
